contract InvMutTest {
    C c;
    uint received;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint contractEtherBefore = address(c).balance;
        received = 0;
        c.withdrawBalance(); if (__ESBMC_reverted()) return;
        uint balAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        assert(balBefore == amount && balAfter == 0 && received == amount && address(c).balance == contractEtherBefore - amount);
    }
    receive() external payable { received += msg.value; }
}

