// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;
    uint received;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 balBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint contractEtherBefore = address(c).balance;
        received = 0;
        try c.withdrawBalance() {} catch { return; }
        uint256 balAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        assertTrue(balBefore == amount && balAfter == 0 && received == amount && address(c).balance == contractEtherBefore - amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { received += msg.value; }
}
